package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;
import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.client.multiplayer.ServerData;import net.minecraft.client.multiplayer.resolver.ServerAddress;import net.minecraft.network.chat.Component;
import java.util.*;
/** Native pre-login review: never requires an incompatible NeoForge login to download a package. */
public final class BootstrapScreen76 extends MaredScreen {
 private final Screen previous;private final Runnable continuation;private final boolean auto;private final BootstrapService76 service=new BootstrapService76();private String initialGame,initialEndpoint,mode="ONLINE";private EditBox game,endpoint;private Button inspect,trust,download,apply,connect,back,auth,save,forget,clear86;private int left,w,top,scroll,maxScroll;private boolean initialCheck,continued,child;
 public BootstrapScreen76(Screen previous,String game,String endpoint,Runnable continuation,boolean auto){super(tr("title"));this.previous=previous;initialGame=game;initialEndpoint=endpoint;this.continuation=continuation;this.auto=auto;try{if(!game.isBlank())mode=com.fixmer.genesis.technology.server.remote.ServerDirectory76.mode(RemoteService69.root(),game);}catch(Exception ignored){}}
 private static Component tr(String key,Object...args){return Component.translatable("mared.bootstrap76."+key,args);}
 private Button button(String key,int x,int y,int width,Runnable fn){return addRenderableWidget(Button.builder(tr(key),b->fn.run()).bounds(x,y,width,20).build());}
 @Override protected void init(){if(game!=null){initialGame=game.getValue();initialEndpoint=endpoint.getValue();}w=Math.max(250,Math.min(660,width-24));left=(width-w)/2;int bw=(w-8)/3;
  game=addRenderableWidget(new EditBox(font,left,37,(w-4)/2,20,tr("game")));game.setMaxLength(255);game.setValue(initialGame);game.setHint(Component.literal("localhost:25565"));endpoint=addRenderableWidget(new EditBox(font,left+(w+4)/2,37,(w-4)/2,20,tr("endpoint")));endpoint.setMaxLength(2048);endpoint.setValue(initialEndpoint);endpoint.setHint(Component.literal("https://…/genesis/"));
  auth=button("mode."+mode,left,61,bw,()->{mode=mode.equals("ONLINE")?"LOCAL_OFFLINE":"ONLINE";auth.setMessage(tr("mode."+mode));});save=button("save",left+bw+4,61,bw,()->service.save(game.getValue(),endpoint.getValue(),mode));forget=button("forget",left+2*(bw+4),61,bw,()->service.forget(game.getValue()));
  inspect=button("check",left,85,bw,()->service.inspect(game.getValue(),endpoint.getValue(),mode));trust=button("trust",left+bw+4,85,bw,()->confirm("trust",service::trust));download=button("download",left+2*(bw+4),85,bw,service::download);
  clear86=button("clear86",left,109,w,()->confirm("clear86",service::clearPartial86));
  top=137;int bottom=height-51;apply=button("apply",left,bottom,w,()->confirm("apply",service::apply));connect=button("connect",left,height-27,(w-4)/2,()->service.connect(this::continueConnection));back=button("back",left+(w+4)/2,height-27,(w-4)/2,this::onClose);tick();
  if(!initialCheck){initialCheck=true;if(!initialGame.isBlank()&&!initialEndpoint.isBlank())service.inspect(initialGame,initialEndpoint,mode);}
 }
 private void confirm(String type,Runnable action){child=true;minecraft.setScreen(new ConfirmScreen(yes->{child=false;minecraft.setScreen(this);if(yes)action.run();},tr(type+"_title"),tr(type+"_explanation")));}
 @Override public void removed(){if(!child&&!continued)service.close();}
 private void continueConnection(){if(continued||minecraft.screen!=this)return;continued=true;if(continuation!=null)continuation.run();else BootstrapHooks76.direct(()->ConnectScreen.startConnecting(previous,minecraft,ServerAddress.parseString(game.getValue()),new ServerData("Genesis",game.getValue(),ServerData.Type.OTHER),false,null));}
 @Override public void tick(){service.tick();boolean busy=service.busy()||service.running();String phase=service.phase();boolean same=service.bound(game.getValue(),endpoint.getValue(),mode);game.setEditable(!busy);endpoint.setEditable(!busy);auth.active=save.active=forget.active=inspect.active=clear86.active=!busy;trust.active=!busy&&same&&phase.equals("UNTRUSTED");download.active=!busy&&same&&service.canDownload86();download.setMessage(tr(service.retryDownload86()?"retry86":"download"));apply.active=!busy&&same&&phase.equals("DOWNLOADED");connect.active=!busy&&same&&phase.equals("MATCH");back.active=!service.armed();if(phase.equals("RECHECK")||phase.equals("RUNTIME_PENDING")&&BootstrapRuntime76.complete())service.inspect(game.getValue(),endpoint.getValue(),mode);if(auto&&same&&phase.equals("MATCH")&&!continued&&!service.busy())service.connect(this::continueConnection);}
 @Override public boolean isPauseScreen(){return false;}@Override public void onClose(){if(service.armed())return;service.close();minecraft.setScreen(previous);}
 // Opening a confirmation must preserve the preparation; Escape/Back are explicit cancellation.
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,9,0xFFFFFFFF);g.drawString(font,tr("game"),left,26,0xFFCCD0DC,false);g.drawString(font,tr("endpoint"),left+(w+4)/2,26,0xFFCCD0DC,false);List<Component> content=new ArrayList<>();content.add(tr("phase."+service.phase()));var state=service.state();if(state!=null){content.add(tr("release",state.offer().sequence(),state.values().get("generation")));content.add(tr("key",state.offer().signer()));content.add(tr("server_phase."+state.phase()));if(service.recovery())content.add(tr("recovery"));if(service.phase().equals("DOWNLOADING"))content.add(tr("progress",service.bytes()*100/state.offer().bytes()));}if(!service.bound(game.getValue(),endpoint.getValue(),mode)&&state!=null)content.add(tr("changed_fields"));if(!service.error().isBlank())content.add(tr("error."+switch(service.error()){case "BOOTSTRAP86_CONTEXT_CHANGED","BOOTSTRAP86_CONTENT_CHANGED","BOOTSTRAP76_CHANGED"->"changed";case "REMOTE_RESUME_BUSY"->"busy86";case "REMOTE_RESUME_CACHE_FULL","REMOTE_RESUME_CACHE_INVALID"->"cache86";case "REMOTE_RESUME_RANGE"->"range86";case "REMOTE70_OFFLINE"->"offline";case "RECOVERY76_UNAVAILABLE"->"recovery";case "REMOTE_TLS"->"tls";case "REMOTE_TRUST_CHANGED"->"key";case "REMOTE_ROLLBACK","REMOTE_EQUIVOCATION"->"rollback";case "REMOTE_WRONG_VERSION"->"version";default->"unavailable";}));if(service.retryDownload86())content.add(tr("resume86"));if(service.cleared86()>=0)content.add(tr("cleared86",service.cleared86()));if(service.phase().equals("APPLY_REFUSED"))content.add(Component.translatable("mared.remote70.phase."+RemoteApplyService70.phase()));content.add(tr("scope"));
  List<net.minecraft.util.FormattedCharSequence> lines=new ArrayList<>();for(Component c:content)lines.addAll(font.split(c,w-6));int row=font.lineHeight+3,bottom=height-57;maxScroll=Math.max(0,lines.size()*row-Math.max(0,bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var line:lines){if(y+row>=top&&y<bottom)g.drawString(font,line,left,y,0xFFCCD0DC,false);y+=row;}g.disableScissor();}super.render(g,mx,my,dt);}
}
